playback/wave_player.crag.mlir:
// Wave Player
//
// A convenience wrapper around a crag.sampler that provides looping playback,
// start/stop gating, and end-of-file detection for audio wave files.
//
// The player reads from a sampler named "audio" and outputs a mono audio block
// each process() call.  Two events control gating:
//
//   start (void) — enable audio output (latch set)
//   stop  (void) — mute audio output  (latch reset)
//
// The player begins in the "playing" state (latch initialised to 1) so that
// audio flows immediately after a sampler asset is bound, without requiring
// an explicit start event.
//
// Looping:
//   When the `loop` parameter is ≥ 0.5 (i.e. treated as true), the read
//   position wraps modulo the bound asset length and crag.sample uses
//   per-sample modulo addressing so that blocks straddling the file boundary
//   are filled seamlessly from both the end and the beginning of the asset.
//   The result is gapless, click-free looping regardless of whether the asset
//   length is a multiple of the block size.
//
//   When `loop` < 0.5 the read position advances linearly and crag.sample
//   returns silence once the asset is exhausted — the natural end-of-file
//   condition.  The end-of-file is detected internally by comparing the
//   current frame position to the asset length; when it is reached the audio
//   output goes silent (no looping restart).
//
// Parameters:
//   loop  [0, 1]  — 1 = loop continuously, 0 = play once (default 1)
//
// Events:
//   start (void) — resume / un-mute playback
//   stop  (void) — pause / mute playback
//
// Sampler:
//   "audio" — bind a WAV file via crag_bind_audio_by_index(0, ptr, len)
//
// Output: !crag.audio<f32, 0, 1> — mono audio (or silence when muted / past end)
//
// Usage (after crag.include):
//   crag.include "standard-graphs/playback/wave_player.crag.mlir" as "wave_player"
//   ...
//   %audio = crag.subgraph_ref "wave_player"()
//                : () -> !crag.audio<f32, 0, 1>

module {
  crag.graph name = "wave_player" sample_rate = 0 channels = 1 {

    // -------------------------------------------------------------------------
    // Parameters
    // -------------------------------------------------------------------------
    %loop = crag.param "loop" min = 0.0 max = 1.0 default = 1.0 : f32

    // -------------------------------------------------------------------------
    // Events — start gates the output on, stop gates it off.
    // -------------------------------------------------------------------------
    %start_fired, %start_at = crag.event_void "start" : i1, i32
    %stop_fired,  %stop_at  = crag.event_void "stop"  : i1, i32

    // SR latch: set by "start", reset by "stop".
    // Initialised to 1 so playback begins immediately.
    %playing = crag.latch %start_fired, %stop_fired : i1, i1 -> i1
    %playing_f32 = arith.uitofp %playing : i1 to f32

    // -------------------------------------------------------------------------
    // Sampler
    // -------------------------------------------------------------------------
    %s   = crag.sampler "audio" : !crag.sampler<"audio">

    // Query the runtime asset length (in interleaved float samples).
    // Returns 0 when no asset is bound; we guard against zero-division below.
    %len = crag.sampler_length %s : !crag.sampler<"audio"> -> i64

    // -------------------------------------------------------------------------
    // Compute playback position
    // -------------------------------------------------------------------------
    %frame = crag.curframe : i64

    // Guard: replace a zero length with 1 to avoid division by zero.
    // (The resulting modulo is harmless because crag.sample will return silence
    // when no asset is bound regardless of the position.)
    %c0      = arith.constant 0   : i64
    %c1      = arith.constant 1   : i64
    %half    = arith.constant 0.5 : f32
    %len_ok  = arith.cmpi sgt, %len, %c0 : i64
    %safe_len = arith.select %len_ok, %len, %c1 : i64

    // Wrapped position for looping (block-aligned).
    %frame_mod = arith.remsi %frame, %safe_len : i64

    // Select between looping and one-shot position.
    %loop_on = arith.cmpf ogt, %loop, %half : f32
    %pos     = arith.select %loop_on, %frame_mod, %frame : i64

    // -------------------------------------------------------------------------
    // Read audio from the sampler
    // -------------------------------------------------------------------------
    // When looping, pass safe_len as the `end` argument so the lowering wraps
    // each sample index modulo the asset length, eliminating the silence gap
    // and skipped samples that would otherwise occur when a block straddles
    // the end of the audio file.  When not looping, pass 0 to keep the
    // existing behaviour of returning silence once the asset is exhausted.
    %wrap_len = arith.select %loop_on, %safe_len, %c0 : i64

    // Sampler output is pinned MONO (`<f32, 0, 1>`) rather than the
    // channel-agnostic `<f32, 0, 0>` placeholder.  Reason: the runtime audio
    // asset bound through `crag_bind_audio_by_index` is laid out as a flat,
    // interleaved-at-source-channels float buffer, and `crag.sample` reads
    // `blockSize * out_channels` consecutive samples starting at `pos`.  If
    // the output type were widened uniformly to the host engine's channel
    // count (e.g. 2 for a stereo engine), a mono wave file would be read at
    // *twice* the expected rate and re-interpreted as stereo interleaved —
    // producing playback at the wrong pitch with audible block-boundary
    // discontinuities, because `pos` advances by `blockSize` per block while
    // the sampler reads `2 * blockSize` samples (a 50%-overlap rewind every
    // block).  Pinning the interior to mono keeps `nSamp == blockSize` per
    // block (one source sample per output frame) and lets the engine's
    // `crag-inject-channel-mixers` pass upmix this mono signal to the host
    // channel count *at the wrapper boundary* — the same path
    // `mono_synth` / `random-wave` take.
    %audio_raw = crag.sample %s, %pos, %wrap_len
                     : !crag.sampler<"audio">, i64, i64
                       -> !crag.audio<f32, 0, 1>

    // -------------------------------------------------------------------------
    // Gate by playing state
    // -------------------------------------------------------------------------
    %audio = crag.scale %audio_raw, %playing_f32
                 : !crag.audio<f32, 0, 1>, f32 -> !crag.audio<f32, 0, 1>

    // -------------------------------------------------------------------------
    // Progress meter: normalized playback position [0, 1]
    // -------------------------------------------------------------------------
    %len_f32   = arith.sitofp %safe_len : i64 to f32
    %frame_f32 = arith.sitofp %frame_mod : i64 to f32
    %progress  = arith.divf %frame_f32, %len_f32 : f32
    crag.meter "progress" %progress min = 0.0 max = 1.0 : f32

    crag.output %audio : !crag.audio<f32, 0, 1>
  }
}

resamplers/thiran-resampler.crag.mlir:
// Thiran Resampler (Allpass-Chain Fractional Delay)
//
// Implements sample-rate conversion using a chain of four first-order Thiran
// allpass sections.  Thiran allpass filters provide maximally-flat group delay
// (to first order) at zero frequency and low phase distortion, making them
// well-suited for fractional-delay resampling.
//
// Algorithm (single first-order Thiran allpass section as Schroeder allpass):
//
//   Given fractional delay D = ratio = in_sr / out_sr and the Thiran
//   first-order allpass coefficient:
//
//     g = (D − 1) / (D + 1)
//
//   Each section implements the Schroeder allpass recurrence:
//
//     v[n] =  x[n] + g · v[n − B]       (B = block_size, in samples)
//     y[n] =  v[n − B] − g · x[n]
//
//   Four sections are chained: the output of section k feeds the input of
//   section k+1.  Chaining increases the effective group-delay flatness and
//   roll-off steepness of the combined transfer function.
//
//   An anti-aliasing 2nd-order Butterworth lowpass (cutoff = ratio) is
//   applied to the input before the allpass chain.
//
// Parameters:
//   ratio  [0.01, 1.0]  in_sr / out_sr  (default ≈ 0.9188 = 44100/48000)
//
// Usage (after crag.include):
//   %out = crag.subgraph_ref "thiran_resampler"(%in)
//              : (!crag.audio<f32, 48000, 1>) -> !crag.audio<f32, 48000, 1>

module {
  crag.graph name = "thiran_resampler" sample_rate = 48000 channels = 1 default_visualizer = "oscilloscope" {
  ^bb0(%input: !crag.audio<f32, 0, 0>):

    // -----------------------------------------------------------------------
    // Parameter: in_sr / out_sr ratio
    // -----------------------------------------------------------------------
    %ratio = crag.param "ratio" min = 0.01 max = 1.0 default = 0.91875 : f32

    // -----------------------------------------------------------------------
    // Anti-aliasing lowpass at normalised cutoff = ratio / 2
    // crag.get_filter_coeffs uses K = tan(pi * cutoff) with cutoff in [0, 0.5]
    // where 0.5 = Nyquist.  ratio is in [0, 1] (1 = Nyquist), so divide by 2.
    // -----------------------------------------------------------------------
    %half   = arith.constant 0.5 : f32
    %cutoff_aa = arith.mulf %ratio, %half : f32
    %fb_aa, %ff_aa = crag.get_filter_coeffs %cutoff_aa order = 2 type = "lowpass"
                         : f32, !crag.coeff_vec, !crag.coeff_vec
    %aa = crag.filter %input, %fb_aa, %ff_aa
              : (!crag.audio<f32, 0, 0>, !crag.coeff_vec, !crag.coeff_vec)
                -> !crag.audio<f32, 0, 0>

    // -----------------------------------------------------------------------
    // Thiran coefficient: g = (ratio − 1) / (ratio + 1)
    // -----------------------------------------------------------------------
    %one   = arith.constant 1.0 : f32
    %num   = arith.subf %ratio, %one : f32   // ratio − 1
    %den   = arith.addf %ratio, %one : f32   // ratio + 1
    %g     = arith.divf %num, %den : f32     // g = (ratio−1)/(ratio+1)
    %neg_g = arith.negf %g : f32             // −g

    // -----------------------------------------------------------------------
    // Thiran allpass section 1
    //   v[n] =  x[n] + g · v[n−B]
    //   y[n] =  v[n−B] − g · x[n]
    // -----------------------------------------------------------------------
    %dl1  = crag.delay_line : !crag.delay<f32, 48000, 1, 512>
    %v1d  = crag.pop_delay %dl1 : !crag.delay<f32, 48000, 1, 512>
                -> !crag.audio<f32, 0, 0>
    %g_v1d  = crag.scale %v1d, %g    : !crag.audio<f32, 0, 0>, f32 -> !crag.audio<f32, 0, 0>
    %v1     = crag.sum %aa, %g_v1d   : (!crag.audio<f32, 0, 0>, !crag.audio<f32, 0, 0>) -> !crag.audio<f32, 0, 0>
    crag.push_delay %dl1, %v1 : !crag.delay<f32, 48000, 1, 512>, !crag.audio<f32, 0, 0>
    %ng_aa  = crag.scale %aa, %neg_g : !crag.audio<f32, 0, 0>, f32 -> !crag.audio<f32, 0, 0>
    %s1     = crag.sum %v1d, %ng_aa  : (!crag.audio<f32, 0, 0>, !crag.audio<f32, 0, 0>) -> !crag.audio<f32, 0, 0>

    // -----------------------------------------------------------------------
    // Thiran allpass section 2
    // -----------------------------------------------------------------------
    %dl2  = crag.delay_line : !crag.delay<f32, 48000, 1, 512>
    %v2d  = crag.pop_delay %dl2 : !crag.delay<f32, 48000, 1, 512>
                -> !crag.audio<f32, 0, 0>
    %g_v2d  = crag.scale %v2d, %g    : !crag.audio<f32, 0, 0>, f32 -> !crag.audio<f32, 0, 0>
    %v2     = crag.sum %s1, %g_v2d   : (!crag.audio<f32, 0, 0>, !crag.audio<f32, 0, 0>) -> !crag.audio<f32, 0, 0>
    crag.push_delay %dl2, %v2 : !crag.delay<f32, 48000, 1, 512>, !crag.audio<f32, 0, 0>
    %ng_s1  = crag.scale %s1, %neg_g : !crag.audio<f32, 0, 0>, f32 -> !crag.audio<f32, 0, 0>
    %s2     = crag.sum %v2d, %ng_s1  : (!crag.audio<f32, 0, 0>, !crag.audio<f32, 0, 0>) -> !crag.audio<f32, 0, 0>

    // -----------------------------------------------------------------------
    // Thiran allpass section 3
    // -----------------------------------------------------------------------
    %dl3  = crag.delay_line : !crag.delay<f32, 48000, 1, 512>
    %v3d  = crag.pop_delay %dl3 : !crag.delay<f32, 48000, 1, 512>
                -> !crag.audio<f32, 0, 0>
    %g_v3d  = crag.scale %v3d, %g    : !crag.audio<f32, 0, 0>, f32 -> !crag.audio<f32, 0, 0>
    %v3     = crag.sum %s2, %g_v3d   : (!crag.audio<f32, 0, 0>, !crag.audio<f32, 0, 0>) -> !crag.audio<f32, 0, 0>
    crag.push_delay %dl3, %v3 : !crag.delay<f32, 48000, 1, 512>, !crag.audio<f32, 0, 0>
    %ng_s2  = crag.scale %s2, %neg_g : !crag.audio<f32, 0, 0>, f32 -> !crag.audio<f32, 0, 0>
    %s3     = crag.sum %v3d, %ng_s2  : (!crag.audio<f32, 0, 0>, !crag.audio<f32, 0, 0>) -> !crag.audio<f32, 0, 0>

    // -----------------------------------------------------------------------
    // Thiran allpass section 4
    // -----------------------------------------------------------------------
    %dl4  = crag.delay_line : !crag.delay<f32, 48000, 1, 512>
    %v4d  = crag.pop_delay %dl4 : !crag.delay<f32, 48000, 1, 512>
                -> !crag.audio<f32, 0, 0>
    %g_v4d  = crag.scale %v4d, %g    : !crag.audio<f32, 0, 0>, f32 -> !crag.audio<f32, 0, 0>
    %v4     = crag.sum %s3, %g_v4d   : (!crag.audio<f32, 0, 0>, !crag.audio<f32, 0, 0>) -> !crag.audio<f32, 0, 0>
    crag.push_delay %dl4, %v4 : !crag.delay<f32, 48000, 1, 512>, !crag.audio<f32, 0, 0>
    %ng_s3  = crag.scale %s3, %neg_g : !crag.audio<f32, 0, 0>, f32 -> !crag.audio<f32, 0, 0>
    %output = crag.sum %v4d, %ng_s3  : (!crag.audio<f32, 0, 0>, !crag.audio<f32, 0, 0>) -> !crag.audio<f32, 0, 0>

    crag.output %output : !crag.audio<f32, 0, 0>
  }
}
